-- =====================================================================================
-- Flowmerce central database · 070 · SEO & Blog module (schema seo)
-- A 1:1 port of the SQLite schema in src/flowmerce/modules/seo/db.py (migrations 1 + 2).
-- Every table, column, unique rule and index is kept, so no SEO feature is lost.
--
-- Type changes (SQLite -> PostgreSQL), applied consistently:
--   INTEGER PRIMARY KEY      -> bigint generated by default as identity (old ids are kept on copy;
--                               the identity is moved past the highest id after loading)
--   0/1 INTEGER flags        -> boolean          (users.active, articles.shopify_published, automation_state.paused)
--   *_json TEXT              -> jsonb
--   ISO-8601 text timestamps -> timestamptz      (*_at, ts, source_timestamp, imported_at)
--   date text                -> date             (gsc/ga4 date, start_date, end_date, source_date)
--   REAL                     -> double precision
--   COLLATE NOCASE email     -> unique index on lower(email)
-- brand_id keeps its current values ('ridhi', 'cpc') and now references ops.stores.legacy_code.
-- Phase 4 ports the SEO Python SQL to these types; until then SEO keeps running on SQLite.
-- Safe to run more than once.
-- =====================================================================================

-- ---------------------------------------------------------------- users (local operator; merged with ops.people at Phase 5)
create table if not exists seo.users (
  id             bigint generated by default as identity primary key,
  email          text not null,
  name           text not null,
  role           text not null check (role in ('admin','seo_manager','reviewer')),
  password_hash  text not null,                                       -- obsolete in local-operator mode; kept, never exposed
  active         boolean not null default true,
  created_at     timestamptz not null,
  last_login_at  timestamptz
);
create unique index if not exists users_email_lower on seo.users (lower(email));

-- ---------------------------------------------------------------- sessions (obsolete, kept per "do not delete")
create table if not exists seo.sessions (
  id          text primary key,
  user_id     bigint not null references seo.users(id) on delete cascade,
  created_at  timestamptz not null,
  expires_at  timestamptz not null
);

-- ---------------------------------------------------------------- brand_settings
create table if not exists seo.brand_settings (
  brand_id       text primary key references ops.stores(legacy_code),
  settings_json  jsonb not null default '{}',
  updated_at     timestamptz,
  updated_by     bigint
);

-- ---------------------------------------------------------------- topics
create table if not exists seo.topics (
  id                  bigint generated by default as identity primary key,
  brand_id            text not null references ops.stores(legacy_code),
  title               text not null,
  primary_keyword     text not null,
  keyword_norm        text not null,
  secondary_keywords  text not null default '',
  intent              text not null default 'informational',
  search_volume       int,
  keyword_difficulty  int,
  volume_source       text,
  rationale           text not null default '',
  notes               text not null default '',
  validation_note     text not null default '',
  status              text not null default 'proposed',
  source              text not null default 'manual',
  owner_id            bigint,
  created_by          bigint,
  created_at          timestamptz not null,
  updated_at          timestamptz not null,
  source_updated_at   timestamptz,
  unique (brand_id, keyword_norm)
);

-- ---------------------------------------------------------------- keywords
create table if not exists seo.keywords (
  id                  bigint generated by default as identity primary key,
  brand_id            text not null references ops.stores(legacy_code),
  keyword             text not null,
  keyword_norm        text not null,
  search_volume       int,
  keyword_difficulty  int,
  intent              text,
  source_tool         text not null default 'manual',
  source_date         date,
  notes               text not null default '',
  source              text not null default 'manual',
  created_at          timestamptz not null,
  updated_at          timestamptz not null,
  unique (brand_id, keyword_norm)
);

-- ---------------------------------------------------------------- articles
create table if not exists seo.articles (
  id                  bigint generated by default as identity primary key,
  brand_id            text not null references ops.stores(legacy_code),
  topic_id            bigint references seo.topics(id) on delete set null,
  title               text not null,
  handle              text not null,
  primary_keyword     text not null default '',
  meta_title          text not null default '',
  meta_description    text not null default '',
  summary_html        text not null default '',
  body_html           text not null default '',
  tags                text not null default '',
  author              text not null default '',
  image_url           text not null default '',
  image_alt           text not null default '',
  status              text not null default 'draft',
  assignee_id         bigint references seo.users(id) on delete set null,
  version             int not null default 1,
  content_hash        text not null default '',
  approved_hash       text,
  approved_by         bigint,
  approved_at         timestamptz,
  review_note         text not null default '',
  shopify_blog_id     text,
  shopify_article_id  text,
  shopify_published   boolean not null default false,
  live_hash           text,
  live_url            text,
  publish_at          timestamptz,
  published_at        timestamptz,
  shopify_synced_at   timestamptz,
  origin              text not null default 'app',
  last_error          text,
  created_by          bigint,
  created_at          timestamptz not null,
  updated_at          timestamptz not null,
  unique (brand_id, handle)
);
create index if not exists articles_status on seo.articles (brand_id, status);
-- ADDITIONS (audit section 8.1 / 15: queries that run today without an index)
create index if not exists articles_topic on seo.articles (topic_id);
create index if not exists articles_shopify on seo.articles (brand_id, shopify_article_id);

-- ---------------------------------------------------------------- article_revisions
create table if not exists seo.article_revisions (
  id            bigint generated by default as identity primary key,
  article_id    bigint not null references seo.articles(id) on delete cascade,
  version       int not null,
  data_json     jsonb not null,
  content_hash  text not null,
  user_id       bigint,
  note          text not null default '',
  created_at    timestamptz not null
);
create index if not exists revisions_article on seo.article_revisions (article_id, version);

-- ---------------------------------------------------------------- review_notes
create table if not exists seo.review_notes (
  id             bigint generated by default as identity primary key,
  article_id     bigint not null references seo.articles(id) on delete cascade,
  user_id        bigint,
  reviewer_name  text not null default '',
  kind           text not null,
  note           text not null default '',
  version        int,
  source         text not null default 'app',
  created_at     timestamptz not null
);
create index if not exists review_notes_article on seo.review_notes (article_id);   -- ADDITION

-- ---------------------------------------------------------------- publish_requests
create table if not exists seo.publish_requests (
  id             bigint generated by default as identity primary key,
  article_id     bigint not null references seo.articles(id) on delete cascade,
  brand_id       text not null references ops.stores(legacy_code),
  mode           text not null check (mode in ('publish_now','schedule','update_live')),
  publish_at     timestamptz,
  content_hash   text not null,
  version        int not null,
  status         text not null default 'pending',
  requested_by   bigint,
  requested_at   timestamptz not null,
  note           text not null default '',
  decided_by     bigint,
  decided_at     timestamptz,
  decision_note  text not null default '',
  executed_at    timestamptz,
  attempts       int not null default 0,
  error          text
);
create index if not exists publish_requests_article on seo.publish_requests (article_id);   -- ADDITION

-- ---------------------------------------------------------------- workflow_runs
create table if not exists seo.workflow_runs (
  id            bigint generated by default as identity primary key,
  brand_id      text not null references ops.stores(legacy_code),
  stage         text not null,
  status        text not null,
  trigger_kind  text not null default 'manual',
  message       text not null default '',
  error         text,
  details_json  jsonb not null default '{}',
  user_id       bigint,
  retry_of      bigint,
  started_at    timestamptz not null,
  finished_at   timestamptz
);
create index if not exists runs_stage on seo.workflow_runs (brand_id, stage, started_at);

-- ---------------------------------------------------------------- automation_state
create table if not exists seo.automation_state (
  brand_id   text primary key references ops.stores(legacy_code),
  paused     boolean not null default false,
  paused_by  bigint,
  paused_at  timestamptz,
  reason     text not null default ''
);

-- ---------------------------------------------------------------- integration_status
-- brand_id '' means "not per brand" in the current code, so no foreign key here.
create table if not exists seo.integration_status (
  key              text not null,
  brand_id         text not null default '',
  status           text not null,
  mode             text not null default '',
  last_attempt_at  timestamptz,
  last_success_at  timestamptz,
  last_error       text,
  details_json     jsonb not null default '{}',
  primary key (key, brand_id)
);

-- ---------------------------------------------------------------- gsc_page_daily
create table if not exists seo.gsc_page_daily (
  brand_id          text not null references ops.stores(legacy_code),
  date              date not null,
  page              text not null,
  clicks            int not null,
  impressions       int not null,
  ctr               double precision not null,
  position          double precision not null,
  source            text not null,
  source_timestamp  timestamptz,
  imported_at       timestamptz not null,
  primary key (brand_id, source, date, page)
);

-- ---------------------------------------------------------------- gsc_query_period
create table if not exists seo.gsc_query_period (
  brand_id          text not null references ops.stores(legacy_code),
  start_date        date not null,
  end_date          date not null,
  page              text not null default '',
  query             text not null,
  clicks            int not null,
  impressions       int not null,
  ctr               double precision not null,
  position          double precision not null,
  source            text not null,
  source_timestamp  timestamptz,
  imported_at       timestamptz not null,
  primary key (brand_id, source, start_date, end_date, page, query)
);

-- ---------------------------------------------------------------- ga4_page_daily
create table if not exists seo.ga4_page_daily (
  brand_id                text not null references ops.stores(legacy_code),
  date                    date not null,
  page_path               text not null,
  sessions                int not null,
  engaged_sessions        int not null,
  engagement_rate         double precision not null,
  avg_engagement_seconds  double precision not null,
  key_events              double precision not null,
  source                  text not null,
  source_timestamp        timestamptz,
  imported_at             timestamptz not null,
  primary key (brand_id, source, date, page_path)
);

-- ---------------------------------------------------------------- products
create table if not exists seo.products (
  brand_id      text not null references ops.stores(legacy_code),
  handle        text not null,
  title         text not null,
  url           text not null,
  image_url     text not null default '',
  product_type  text not null default '',
  synced_at     timestamptz not null,
  source        text not null,
  primary key (brand_id, handle)
);

-- ---------------------------------------------------------------- audit_log (shared by both modules from Phase 3)
create table if not exists seo.audit_log (
  id            bigint generated by default as identity primary key,
  ts            timestamptz not null,
  user_id       bigint,
  user_email    text,
  action        text not null,
  entity_type   text not null default '',
  entity_id     text not null default '',
  brand_id      text not null default '',
  summary       text not null default '',
  details_json  jsonb not null default '{}',
  ip            text
);
create index if not exists audit_ts on seo.audit_log (ts);
create index if not exists audit_brand on seo.audit_log (brand_id, ts);   -- ADDITION

-- ---------------------------------------------------------------- imports
create table if not exists seo.imports (
  id           bigint generated by default as identity primary key,
  kind         text not null,
  filename     text not null,
  user_id      bigint,
  created_at   timestamptz not null,
  rows_total   int not null,
  inserted     int not null,
  updated      int not null,
  duplicates   int not null,
  rejected     int not null,
  errors_json  jsonb not null default '[]'
);

-- ---------------------------------------------------------------- ai_jobs (migration 2)
create table if not exists seo.ai_jobs (
  id                text primary key,
  brand_id          text not null references ops.stores(legacy_code),
  stage             text not null,
  task_type         text not null,
  input_json        jsonb not null default '{}',
  status            text not null default 'pending' check (status in ('pending','queued','running','succeeded','failed','cancelled')),
  provider          text not null,
  worker_id         text,
  external_id       text,
  retry_count       int not null default 0,
  max_retries       int not null default 3,
  attempts          int not null default 0,
  run_number        int not null default 1,
  progress          int not null default 0,
  message           text not null default '',
  error             text,
  error_kind        text,
  result_json       jsonb,
  workflow_run_id   bigint,
  idempotency_key   text unique,
  dedupe_key        text,
  last_sequence     int not null default 0,
  lease_owner       text,
  lease_expires_at  timestamptz,
  next_attempt_at   timestamptz,
  accepted_at       timestamptz,
  created_by        bigint,
  created_at        timestamptz not null,
  started_at        timestamptz,
  last_progress_at  timestamptz,
  finished_at       timestamptz,
  updated_at        timestamptz not null
);
create index if not exists ai_jobs_queue on seo.ai_jobs (status, provider, next_attempt_at);
create index if not exists ai_jobs_brand on seo.ai_jobs (brand_id, created_at);
create unique index if not exists ai_jobs_active_dedupe on seo.ai_jobs (dedupe_key)
  where dedupe_key is not null and status in ('pending','queued','running');

-- ---------------------------------------------------------------- ai_job_events
create table if not exists seo.ai_job_events (
  id           bigint generated by default as identity primary key,
  job_id       text not null references seo.ai_jobs(id),
  event_id     text not null,
  source       text not null default 'worker',
  sequence     int,
  event_type   text not null,
  status       text,
  progress     int,
  message      text not null default '',
  agent        text,
  external_id  text,
  created_at   timestamptz not null,
  unique (job_id, event_id)
);
create index if not exists ai_job_events_job on seo.ai_job_events (job_id, id);
